"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "Baru saja anjing pergi, rubah mengendap di sekitar kandang. Usir mereka kembali ke padang",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "Babi hutan memakan panen petani. Musim dingin tanpa persediaan akan jadi akhir kami",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "Di tepi padang menyala Batu Amarah. Amarahnya membuat hewan mengamuk – hancurkan",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "Untung Bao mengirimmu. Bandit menyerang setiap pedagang di jalan hutan. Usir mereka",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "Babi hutan di sini berduri, bukan berbulu. Mereka mencabik perangkap kami – dan pemasangnya",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "Jauh di hutan, laba-laba raksasa memintal jaring di atas jalan. Bakar jika perlu",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "Di tengah hutan tumbuh Batu Duri. Sulurnya mencekik setiap pohon. Hancurkan",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "Hagen mengirimmu? Ayo, para orc sudah di depan pagar kayu kami. Lemahkan pasukan mereka",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "Para orc memelihara hyena seperti anjing dan melepaskannya ke pengintai kami. Habisi kawanan itu",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "Idris mengirimmu? Para dewa berbaik hati pada Sahra. Kobra mengintai di setiap sumber air",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "Dengar suara derik itu? Ular derik. Ratusan. Kafilah tak berani berangkat lagi",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "Di Puncak Beku terlihat yeti sebesar rumah. Bawa bulunya sebagai bukti",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "Mamut mengamuk sejak dingin tak kunjung pergi. Mereka menginjak-injak gubuk persediaan kami",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "Di tempat Batu Kesunyian berdiri, setiap lagu membisu. Kembalikan suara ke puncak",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "Batu Jiwa terakhir dan terkuat. Hancurkan, dan batu-batu berhenti tumbuh",
